        ('intro.first', 'Lần đầu gọi animateFloatAsState(0f)', 'The first call to animateFloatAsState(0f)', 'Composable chạy lần đầu với target 0.', 'The composable runs for the first time with target 0.'),
        ('intro.change', 'Target sẽ đổi từ 0 lên 100', 'The target will change from 0 to 100', 'Ví dụ: một nút đổi `toggled`, và target là `if (toggled) 100f else 0f`.', 'For example: a button flips `toggled`, and the target is `if (toggled) 100f else 0f`.'),
        ('intro.interrupt', 'Đổi target khi đang chạy', 'Changing the target while running', 'Target lên 100, rồi khi giá trị mới tới khoảng giữa, target đổi sang 40.', 'The target goes to 100, then, when the value is about half-way, the target changes to 40.'),
        ('intro.same', 'Recompose vì lý do khác', 'Recomposing for another reason', 'Giá trị đã ở 100; composable chạy lại vì một state khác, target vẫn 100.', 'The value is already at 100; the composable re-runs because of another state, and the target is still 100.'),
        ('create', 'remember tạo AnimateAsState', 'remember creates AnimateAsState', '`remember { AnimateAsState(target, …) }` tạo một `Animatable(0f)`; khối remember đặt `updating = false`, nên lần đầu KHÔNG có `SideEffect`, không có animation: giá trị bắt đầu đúng bằng target.', '`remember { AnimateAsState(target, …) }` creates an `Animatable(0f)`; the remember block sets `updating = false`, so the first time there is NO `SideEffect` and no animation: the value starts exactly at the target.'),
        ('read', 'Đọc state.value', 'Reading state.value', 'Giá trị trả về là `State<Float>`; đọc nó là đọc `animatable.value` (qua `asState()`), một snapshot state.', 'The returned value is a `State<Float>`; reading it reads `animatable.value` (via `asState()`), a snapshot state.'),
        ('end.first', 'Kết thúc: không job nào', 'The end: no job at all', 'Lần đầu chỉ dựng đồ, không chạy.', 'The first time only builds things; nothing runs.'),
        ('recompose', 'Recompose với target 100 → SideEffect gọi update()', 'Recompose with target 100 → SideEffect calls update()', 'Sau khi composition apply, `SideEffect` gọi `state.update(100f, …)`. Vì 100 khác `animatable.targetValue` (0), cần chạy lại animation.', 'After composition applies, `SideEffect` calls `state.update(100f, …)`. Because 100 differs from `animatable.targetValue` (0), the animation must (re)start.'),
        ('recomposeSame', 'Recompose với target 100 như cũ', 'Recompose with the same target 100', '`SideEffect` vẫn gọi `update()` sau mỗi lần recompose.', '`SideEffect` still calls `update()` after every recomposition.'),
        ('noop', 'target == targetValue → không làm gì', 'target == targetValue → nothing to do', 'Không đổi type converter, không đổi label, target bằng: không restart, không job mới.', 'No converter change, no label change, an equal target: no restart, no new job.'),
        ('end.same', 'Kết thúc: 0 job', 'The end: 0 jobs', 'Recompose thường xuyên không tự tạo animation mới.', 'Frequent recomposition does not create new animations by itself.'),
        ('launch', 'restartAnimation: chạy animateTo(100)', 'restartAnimation: launches animateTo(100)', '`job?.cancel()` (chưa có job), rồi `coroutineScope.launch(start = UNDISPATCHED) { animatable.animateTo(100f, spec) }`. Scope đến từ `rememberCoroutineScope()`, nên job sống theo composable (chương EF của Runtime).', '`job?.cancel()` (no job yet), then `coroutineScope.launch(start = UNDISPATCHED) { animatable.animateTo(100f, spec) }`. The scope comes from `rememberCoroutineScope()`, so the job lives as long as the composable (Runtime chapter EF).'),
        ('frame', 'Frame: giá trị = {v}', 'Frame: value = {v}', '`animateTo` đặt giá trị mới mỗi frame; ai đọc `state.value` trong composition sẽ recompose, đọc trong `graphicsLayer {}` hay `offset {}` thì chỉ layout/draw (C7).', '`animateTo` sets a new value every frame; whoever reads `state.value` in composition recomposes, while reading it in `graphicsLayer {}` or `offset {}` only re-runs layout/draw (C7).'),
        ('frame2', 'Frame: giá trị = {v}', 'Frame: value = {v}', 'Spring mới mang theo vận tốc cũ, nên giá trị còn đi lên một chút trước khi quay về 40.', 'The new spring carries the old velocity, so the value still rises a little before turning back towards 40.'),
        ('settle', 'Animation xong, finishedListener', 'The animation finishes, finishedListener', 'Khi `animateTo` trả về, `finishedListener` (nếu có) được gọi với giá trị cuối. Ví dụ dùng nó để in ra màu cuối cùng.', 'When `animateTo` returns, `finishedListener` (if any) is called with the final value. For example, to print the final colour.'),
        ('end.change', 'Kết thúc: 1 job, giá trị 100', 'The end: 1 job, value 100', 'Một lần đổi target, một coroutine.', 'One target change, one coroutine.'),
        ('retarget', 'Target đổi sang 40: hủy job cũ, launch job mới', 'The target changes to 40: cancel the old job, launch a new one', '`update()` thấy 40 ≠ 100 và `animatable.isRunning`, nên `isInterrupted = true`; `restartAnimation` gọi `job?.cancel()` rồi launch `animateTo(40f)`. Animatable bắt đầu từ giá trị hiện tại (52), không nhảy.', '`update()` sees 40 ≠ 100 and `animatable.isRunning`, so `isInterrupted = true`; `restartAnimation` calls `job?.cancel()` and launches `animateTo(40f)`. The Animatable starts from the current value (52), without jumping.'),
        ('end.interrupt', 'Kết thúc: 2 job, 1 bị cancel, giá trị 40', 'The end: 2 jobs, 1 cancelled, value 40', 'Bạn không phải viết gì để xử lý việc ngắt.', 'You write nothing to handle the interruption.'),
